import{_ as t,c as o,o as r,a5 as n}from"./chunks/framework.DuCYAsAJ.js";const g=JSON.parse('{"title":"内容与 Feed API 处理器","description":"","frontmatter":{"title":"内容与 Feed API 处理器","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#2.3","branch":"main","level":1,"order":2.3},"headers":[],"relativePath":"posts/projects/zfeed/02-front-api-gateway/03-content-and-feed-api-handlers.md","filePath":"posts/projects/zfeed/02-front-api-gateway/03-content-and-feed-api-handlers.md","lastUpdated":1779632679000}'),c={name:"posts/projects/zfeed/02-front-api-gateway/03-content-and-feed-api-handlers.md"};function a(i,e,l,p,d,b){return r(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="内容与-feed-api-处理器" tabindex="-1">内容与 Feed API 处理器 <a class="header-anchor" href="#内容与-feed-api-处理器" aria-label="Permalink to &quot;内容与 Feed API 处理器&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/content/content.api" target="_blank" rel="noreferrer">app/front/doc/content/content.api</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/front.api" target="_blank" rel="noreferrer">app/front/doc/front.api</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/handler/content/publisharticlehandler_parse_test.go" target="_blank" rel="noreferrer">app/front/internal/handler/content/publisharticlehandler_parse_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/handler/routes.go" target="_blank" rel="noreferrer">app/front/internal/handler/routes.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/handler/user/uploadavatarhandler.go" target="_blank" rel="noreferrer">app/front/internal/handler/user/uploadavatarhandler.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/contentuploadscredentialslogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/content/contentuploadscredentialslogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/deletecontentlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/content/deletecontentlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/getcontentdetaillogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/content/getcontentdetaillogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/getcontentdetaillogic_test.go" target="_blank" rel="noreferrer">app/front/internal/logic/content/getcontentdetaillogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/publisharticlelogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/content/publisharticlelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/publishlogic_test.go" target="_blank" rel="noreferrer">app/front/internal/logic/content/publishlogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/publishvideologic.go" target="_blank" rel="noreferrer">app/front/internal/logic/content/publishvideologic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/feed/followlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/feed/followlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/feed/recommendlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/feed/recommendlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/feed/userfavoritelogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/feed/userfavoritelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/feed/userpublishlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/feed/userpublishlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/querylikeinfologic.go" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/querylikeinfologic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/content/content.pb.go" target="_blank" rel="noreferrer">app/rpc/content/content/content.pb.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/content/content_grpc.pb.go" target="_blank" rel="noreferrer">app/rpc/content/content/content_grpc.pb.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/declogic.go" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/declogic.go</a></li></ul></details><p><code>front-api</code> 网关是所有内容相关操作的主要入口。这些处理器负责在客户端和 <code>content-rpc</code> 服务之间编排请求，处理认证上下文，并将 RESTful HTTP 请求映射为 gRPC 调用。</p><h2 id="内容生命周期处理器" tabindex="-1">内容生命周期处理器 <a class="header-anchor" href="#内容生命周期处理器" aria-label="Permalink to &quot;内容生命周期处理器&quot;">​</a></h2><p>内容生命周期处理器负责文章和视频的创建、修改与删除。这些处理器要求用户强制登录，认证由 <code>UserLoginStatusAuthMiddleware</code> 执行。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/content/content.api#L102-L107" target="_blank" rel="noreferrer">app/front/doc/content/content.api#102-107</a></p><h3 id="发布操作" tabindex="-1">发布操作 <a class="header-anchor" href="#发布操作" aria-label="Permalink to &quot;发布操作&quot;">​</a></h3><p>系统区分两种主要内容类型：<code>ARTICLE</code> 和 <code>VIDEO</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto#L7-L11" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto#7-11</a></p><ul><li>PublishArticle：由 <code>PublishArticleLogic</code> 处理。它从请求上下文提取 <code>user_id</code>，<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/publisharticlelogic.go#L38-L41" target="_blank" rel="noreferrer">app/front/internal/logic/content/publisharticlelogic.go#38-41</a> 校验必填字段（Title、Content、Visibility），并调用 RPC <code>PublishArticle</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/publisharticlelogic.go#L48-L55" target="_blank" rel="noreferrer">app/front/internal/logic/content/publisharticlelogic.go#48-55</a></li><li>PublishVideo：由 <code>PublishVideoLogic</code> 处理。它在调用 RPC <code>PublishVideo</code> 前，会处理视频专属元数据，例如 <code>VideoUrl</code>、<code>CoverUrl</code> 和 <code>Duration</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto#L244-L244" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto#244</a></li></ul><h3 id="内容编辑与删除" tabindex="-1">内容编辑与删除 <a class="header-anchor" href="#内容编辑与删除" aria-label="Permalink to &quot;内容编辑与删除&quot;">​</a></h3><ul><li>EditArticle / EditVideo：这些处理器使用路径参数传入 <code>content_id</code>，<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/content/content.api#L50-L50" target="_blank" rel="noreferrer">app/front/doc/content/content.api#50</a> 并允许对内容字段执行局部更新。</li><li>DeleteContent：通过将 <code>user_id</code>（用于所有权校验）和 <code>content_id</code> 传给 <code>content-rpc</code> 服务来执行软删除。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto#L234-L237" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto#234-237</a></li></ul><h3 id="内容上传凭证" tabindex="-1">内容上传凭证 <a class="header-anchor" href="#内容上传凭证" aria-label="Permalink to &quot;内容上传凭证&quot;">​</a></h3><p>发布前，客户端必须先获取 OSS（Object Storage Service）的安全上传凭证。<code>ContentUploadsCredentials</code> 处理器会向 RPC 服务请求凭证，并提供 <code>scene</code>（例如文章封面、视频文件）以及文件元数据。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/content/content.api#L6-L11" target="_blank" rel="noreferrer">app/front/doc/content/content.api#6-11</a></p><p>内容操作数据流</p><table tabindex="0"><thead><tr><th>动作</th><th>Handler</th><th>RPC 方法</th><th>关键参数</th></tr></thead><tbody><tr><td>发布文章</td><td><code>PublishArticle</code></td><td><code>ContentService/PublishArticle</code></td><td><code>title</code>、<code>content</code>、<code>visibility</code></td></tr><tr><td>发布视频</td><td><code>PublishVideo</code></td><td><code>ContentService/PublishVideo</code></td><td><code>video_url</code>、<code>duration</code>、<code>cover_url</code></td></tr><tr><td>删除内容</td><td><code>DeleteContent</code></td><td><code>ContentService/DeleteContent</code></td><td><code>content_id</code>（路径参数）</td></tr><tr><td>获取上传凭证</td><td><code>ContentUploadsCredentials</code></td><td><code>ContentService/GetUploadCredentials</code></td><td><code>scene</code>、<code>file_ext</code>、<code>file_size</code></td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/content/content.api#L102-L144" target="_blank" rel="noreferrer">app/front/doc/content/content.api#102-144</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/publisharticlelogic.go#L33-L63" target="_blank" rel="noreferrer">app/front/internal/logic/content/publisharticlelogic.go#33-63</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto#L242-L252" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto#242-252</a></p><h2 id="内容详情获取" tabindex="-1">内容详情获取 <a class="header-anchor" href="#内容详情获取" aria-label="Permalink to &quot;内容详情获取&quot;">​</a></h2><p><code>GetContentDetail</code> 处理器提供单个内容的增强视图。与发布不同，该处理器使用 <code>OptionalLoginMiddleware</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/content/content.api#L150-L151" target="_blank" rel="noreferrer">app/front/doc/content/content.api#150-151</a></p><h3 id="查看者上下文" tabindex="-1">查看者上下文 <a class="header-anchor" href="#查看者上下文" aria-label="Permalink to &quot;查看者上下文&quot;">​</a></h3><p>如果用户已登录，处理器会通过 <code>utils.GetContextUserIdWithDefault</code> 从上下文中提取 <code>viewer_id</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/getcontentdetaillogic.go#L40-L42" target="_blank" rel="noreferrer">app/front/internal/logic/content/getcontentdetaillogic.go#40-42</a> 该 ID 会被传给 RPC 服务，用于判断“查看者状态”，包括：</p><ul><li><code>is_liked</code>：当前查看者是否点赞了该内容。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto#L173-L173" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto#173</a></li><li><code>is_favorited</code>：当前查看者是否收藏了该内容。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto#L174-L174" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto#174</a></li><li><code>is_following_author</code>：当前查看者是否关注了内容作者。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto#L175-L175" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto#175</a></li></ul><h3 id="数据聚合" tabindex="-1">数据聚合 <a class="header-anchor" href="#数据聚合" aria-label="Permalink to &quot;数据聚合&quot;">​</a></h3><p>该逻辑会将复杂的 <code>ContentDetail</code> proto 消息映射为 HTTP 响应使用的 <code>types.ContentDetail</code> 结构体，并确保互动计数（点赞、收藏、评论）被正确序列化。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/getcontentdetaillogic.go#L53-L74" target="_blank" rel="noreferrer">app/front/internal/logic/content/getcontentdetaillogic.go#53-74</a></p><p>内容详情映射图</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/getcontentdetaillogic.go#L32-L75" target="_blank" rel="noreferrer">app/front/internal/logic/content/getcontentdetaillogic.go#32-75</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto#L157-L176" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto#157-176</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/content/content.api#L74-L99" target="_blank" rel="noreferrer">app/front/doc/content/content.api#74-99</a></p><h2 id="feed-api-处理器" tabindex="-1">Feed API 处理器 <a class="header-anchor" href="#feed-api-处理器" aria-label="Permalink to &quot;Feed API 处理器&quot;">​</a></h2><p>Feed API 基于不同算法和用户关系提供内容列表。所有 Feed 处理器都支持基于 cursor 的分页。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto#L76-L116" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto#76-116</a></p><h3 id="_1-推荐-feed" tabindex="-1">1. 推荐 Feed <a class="header-anchor" href="#_1-推荐-feed" aria-label="Permalink to &quot;1. 推荐 Feed&quot;">​</a></h3><p>推荐 Feed 是主要发现机制，用于获取个性化或全局“热门”内容流。</p><ul><li>逻辑：<code>RecommendLogic</code>。</li><li>RPC：<code>FeedService/RecommendFeed</code>。</li><li>快照：支持 <code>snapshot_id</code>，用于保证用户翻页浏览同一组推荐结果时的一致性。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto#L78-L85" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto#78-85</a></li></ul><h3 id="_2-关注-feed" tabindex="-1">2. 关注 Feed <a class="header-anchor" href="#_2-关注-feed" aria-label="Permalink to &quot;2. 关注 Feed&quot;">​</a></h3><p>关注 Feed 是当前查看者所关注用户发布内容组成的时间线。</p><ul><li>逻辑：<code>FollowLogic</code>。</li><li>RPC：<code>FeedService/FollowFeed</code>。</li><li>认证：需要强制登录，以识别用于读取 follow-inbox 的 <code>user_id</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto#L88-L89" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto#88-89</a></li></ul><h3 id="_3-用户发布-feed" tabindex="-1">3. 用户发布 Feed <a class="header-anchor" href="#_3-用户发布-feed" aria-label="Permalink to &quot;3. 用户发布 Feed&quot;">​</a></h3><p>列出指定用户发布的内容。</p><ul><li>逻辑：<code>UserPublishLogic</code>。</li><li>RPC：<code>FeedService/UserPublishFeed</code>。</li><li>可见性：RPC 服务会根据 <code>viewer_id</code> 是否等于 <code>author_id</code> 过滤内容；作者本人可以看到私密内容，陌生查看者只能看到公开内容。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto#L100-L105" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto#100-105</a></li></ul><h3 id="_4-用户收藏-feed" tabindex="-1">4. 用户收藏 Feed <a class="header-anchor" href="#_4-用户收藏-feed" aria-label="Permalink to &quot;4. 用户收藏 Feed&quot;">​</a></h3><p>列出指定用户加入收藏的内容。</p><ul><li>逻辑：<code>UserFavoriteLogic</code>。</li><li>RPC：<code>FeedService/UserFavoriteFeed</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/feed/userfavoritelogic.go#L42-L47" target="_blank" rel="noreferrer">app/front/internal/logic/feed/userfavoritelogic.go#42-47</a></li></ul><p>Feed 架构图</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/proto/content.proto#L254-L259" target="_blank" rel="noreferrer">app/rpc/content/proto/content.proto#254-259</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/feed/userfavoritelogic.go#L32-L76" target="_blank" rel="noreferrer">app/front/internal/logic/feed/userfavoritelogic.go#32-76</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/front.api#L46-L70" target="_blank" rel="noreferrer">app/front/doc/front.api#46-70</a></p><h2 id="错误处理与校验" tabindex="-1">错误处理与校验 <a class="header-anchor" href="#错误处理与校验" aria-label="Permalink to &quot;错误处理与校验&quot;">​</a></h2><p>处理器在发起 RPC 调用前会执行严格校验：</p><ul><li>参数校验：处理器会检查 <code>nil</code> 指针和非法 ID（例如 <code>ContentId &lt;= 0</code>）。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/getcontentdetaillogic.go#L33-L35" target="_blank" rel="noreferrer">app/front/internal/logic/content/getcontentdetaillogic.go#33-35</a></li><li>业务错误：RPC 错误会被包装或直接返回。例如内容不存在时，逻辑返回 <code>errorx.NewNotFound(&quot;内容不存在&quot;)</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/getcontentdetaillogic.go#L49-L50" target="_blank" rel="noreferrer">app/front/internal/logic/content/getcontentdetaillogic.go#49-50</a></li><li>认证错误：如果访问受保护路由时没有有效会话，<code>utils.GetContextUserId</code> 会返回错误，处理器会将其包装为 <code>errorx.NewUnauthorized</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/publisharticlelogic.go#L38-L41" target="_blank" rel="noreferrer">app/front/internal/logic/content/publisharticlelogic.go#38-41</a></li></ul><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/publisharticlelogic.go#L34-L41" target="_blank" rel="noreferrer">app/front/internal/logic/content/publisharticlelogic.go#34-41</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/content/getcontentdetaillogic.go#L33-L50" target="_blank" rel="noreferrer">app/front/internal/logic/content/getcontentdetaillogic.go#33-50</a></p>',44)])])}const h=t(c,[["render",a]]);export{g as __pageData,h as default};
